// ====================================
// CONFIGURACIÓN DE MODELOS
// ====================================
const MODELOS = [
  "Frontier",
  "X-Trail e-Power",
  "X-Trail",
  "Nuevo Kicks",
  //"Kicks Play",
  "Sentra",
  "Versa",
  "Kait"
];

const ALIASES = {
  "kicks sense":   "Nuevo Kicks",
  "kicks advance": "Nuevo Kicks",
  "nissan kicks":  "Nuevo Kicks",
  "kicks":         "Nuevo Kicks",
};

const ORIGIN_MAP = {
  "Frontier":        "meli_frontier_retail",
  "X-Trail e-Power": "meli_xtrail_retail",
  "X-Trail":         "melil_xtrail_retail",
  "Nuevo Kicks":     "meli_nuevokicks_retail",
  "Kicks Play":      "meli_nuevokicks_retail",
  "Sentra":          "meli_sentra_retail",
  "Versa":           "meli_versa_retail",
  "Kait":            "meli_kait_retail"
};

const DETALLE_SALESFORCE_MAP = {
  "Frontier":        "Landing Frontier",
  "X-Trail e-Power": "Landing X-Trail",
  "X-Trail":         "Landing X-Trail",
  "Nuevo Kicks":     "Landing New Kicks",
  "Kicks Play":      "Landing New Kicks",
  "Sentra":          "Landing Sentra",
  "Versa":           "Landing Versa",
  "Kait":            "Kait Retail"
};

// ====================================
// MAPEO DE DEALERS
// ====================================
const DEALER_ASSIGNMENTS = {
  "aika@nissan.com":             ["230112", "230113"],
  "aucam@nissan.com":            ["230311", "230312", "230314"],
  "autogen@nissan.com":          ["230411", "230412", "230421", "230431", "230432", "230433"],
  "autossan@nissan.com":         ["230512", "230513", "230514", "230515", "230516"],
  "tdfmotors@nissan.com":        ["230611", "230612", "230622"],
  "cityssan@nissan.com":         ["230712", "230721", "230722", "230731"],
  "egeoautomotores@nissan.com":  ["230812", "230813", "230814", "230822", "230852"],
  "femotors@nissan.com":         ["230911", "230912", "230914", "230915"],
  "sendai@nissan.com":           ["231111", "231112", "231121", "231132", "231141", "231151", "231161"],
  "kyotoautomotores@nissan.com": ["231311", "231312", "231313", "231314", "231316", "231317"],
  "carone@nissan.com":           ["231611", "231612", "231614", "231651"],
  "nix@nissan.com":              ["231911", "231921", "231931"],
  "noale@nissan.com":            ["232011", "232013", "232021", "232032"],
  "senta@nissan.com":            ["232311", "232312", "232313", "232314"],
  "surisan@nissan.com":          ["232521", "232522", "232531", "232532", "232541"],
  "autoferro@nissan.com":        ["232711", "232712", "232722"],
  "fianiautomotores@nissan.com": ["232911", "232912", "232915", "232916", "232917", "232921", "232922"],
  "yacopinimirai@nissan.com":    ["233012", "233013", "233015"],
  "neostar@nissan.com":          ["233111", "233115"],
  "capital@nissan.com":          ["233211", "233212", "233213", "233214","233215"],
  "agnoa@nissan.com":            ["235013", "235014"],
};

// ====================================
// INICIALIZACIÓN (una sola vez)
// ====================================

// Índice invertido para lookup O(1): { "230112": "aika@nissan.com", ... }
const SUCURSAL_TO_EMAIL = Object.entries(DEALER_ASSIGNMENTS).reduce(
  (acc, [email, ids]) => {
    ids.forEach((id) => (acc[id] = email));
    return acc;
  },
  {}
);

// Modelos normalizados para matching
const modelosNorm = MODELOS.map((m) => ({ raw: m, n: norm(m) }));

// ====================================
// FUNCIONES AUXILIARES
// ====================================

// Normalización robusta: trim, lowercase, colapsa espacios, unifica guiones unicode
function norm(s) {
  return String(s ?? "")
    .trim()
    .toLowerCase()
    .replace(/[‐\-–—]/g, "-")
    .replace(/\s+/g, " ");
}

function resolveModelo(pi) {
  if (pi === undefined || pi === null || String(pi).trim() === "") {
    return { productoInteres: pi ?? null, origin: null };
  }

  const piNorm = norm(pi);

  // 1. Aliases exactos
  const aliasMatch = ALIASES[piNorm];
  if (aliasMatch) {
    return {
      productoInteres: aliasMatch,
      origin: ORIGIN_MAP[aliasMatch] ?? null,
    };
  }

  // 2. Match por "contiene", priorizando el más largo
  //    (evita que "X-Trail" gane sobre "X-Trail e-Power")
  const match = modelosNorm
    .filter((m) => piNorm.includes(m.n))
    .sort((a, b) => b.n.length - a.n.length)[0];

  if (!match) {
    return { productoInteres: pi, origin: null }; // no reconocido → sin tocar
  }

  return {
    productoInteres: match.raw,
    origin: ORIGIN_MAP[match.raw] ?? null,
  };
}

function resolveDealerEmail(sucursalId) {
  const id = String(sucursalId ?? "").trim();
  return id ? (SUCURSAL_TO_EMAIL[id] ?? null) : null;
}

// ====================================
// PROCESAMIENTO PRINCIPAL
// ====================================
return items.map((item) => {
  const { productoInteres, origin } = resolveModelo($('When Executed by Another Workflow').first().json?.productoInteres);
  const pilot_assigned_user = resolveDealerEmail(item.json?.output?.sucursal_id);

  return {
    ...item,
    json: {
      ...item.json,
      productoInteres,
      origin,
      pilot_assigned_user,
      origen_salesforce:     "Internet",
      suborigen_salesforce:  "Mercado Libre",
      detalle_salesforce:    DETALLE_SALESFORCE_MAP[productoInteres] ?? null,
      subdetalle_salesforce: "consulta",
    },
  };
});

